function buildArticle(R,S,subjKey,h,g,jOver,nb){
  const sj=subPools(subjKey), J=jOver||subKo(subjKey);
  const NB=nb&&nb.length?nb.join(", "):"인근 지역";
  const hd=(k,off)=>inj(pick1(HEAD[k],h+off),R,J).replace(/\{J\}/g,J);
  const sec=(id,head,inner)=>`<h2 id="${id}">${esc(head)}</h2>${inner}`;
  const ps=arr=>arr.map(t=>`<p>${esc(inj(t,R,S))}</p>`).join("");
  const introArr=g?[pick1(g.intro,h).replace(/\{J\}/g,J), pick1(sj.intros,h)].concat(pickN(GENERIC.localAngle,h+11,3)):[pick1(sj.intros,h)].concat(pickN(GENERIC.localAngle,h+11,4));
  const intro=sec("s1",hd("s1",0),ps(introArr));
  const rows=(g?g.curri:sj.curri).map(c=>`<tr><td>${esc(c[0])}</td><td>${esc(c[1])}</td><td>${esc(c[2])}</td></tr>`).join("");
    const curri=sec("s2",hd("curri",1),`<p>${esc(inj(pick1(GENERIC.curriIntro,h+23),R,S).replace(/\{J\}/g,J))}</p><table><thead><tr><th>학년</th><th>집중 영역</th><th>목표</th></tr></thead><tbody>${rows}</tbody></table><p>${esc(pick1(subjKey==="ged"?CURRI_EX_GED:CURRI_EX,h+41))}</p>`);
  const trait=sec("s3",hd("trait",2),ps(pickN(sj.traits,h+3,3)));
  const stuck=sec("s4",hd("stuck",4),ps(pickN(sj.stuck,h+5,3)));
  const stepset=pick1(GENERIC.stepsets,h+7);
  const method=sec("s5",hd("method",6),`<p>${esc(inj(pick1(GENERIC.method,h+8),R,S))}</p><ol>${stepset.map(s=>`<li><strong>${esc(s[0])}</strong> — ${esc(s[1])}</li>`).join("")}</ol>`);
  const why=sec("s6",hd("why",9),ps(pickN(GENERIC.why,h+10,5)));
  const study=sec("s7",hd("study",16),`<p>${esc(inj(pick1(GENERIC.studyIntro,h+18),R,S))}</p>`+ps(pickN(sj.study,h+17,4)));
  const envTxt=pickN(GENERIC.localEnv,h+27,2).map(x=>inj(x,R,S).replace(/\{J\}/g,J).replace(/\{N\}/g,NB));
  const localenv=sec("s8",hd("localenv",28),envTxt.map(x=>`<p>${esc(x)}</p>`).join(""));
  const worries=sec("s9",hd("worries",30),ps(pickN(GENERIC.worries,h+31,3).map(x=>x.replace(/\{J\}/g,J))));
  const hpick=pickN(GENERIC.helps,h+33,4);
  const helps=sec("s10",hd("helps",34),`<ul>${hpick.map(x=>`<li><strong>${esc(x[0].replace(/\{J\}/g,J))}</strong> — ${esc(inj(x[1],R,S).replace(/\{J\}/g,J))}</li>`).join("")}</ul>`);
  let gradeSec="";
  if(subjKey!=="ged"){
    if(g){
      const gkey=g.slug==="elementary"?"elem":(g.slug==="middle"?"mid":"high");
      const gtxt=pickN(GRADE_WORRIES[gkey],h+44,2).map(x=>`<p>${esc(x)}</p>`).join("");
      gradeSec=sec("sgrade",pick1(GRADE_HEADS_ONE,h+43).replace("{G}",g.ko),gtxt);
    } else {
      gradeSec=sec("sgrade",pick1(GRADE_HEADS,h+43),`<p><strong>초등</strong> — ${esc(pick1(GRADE_WORRIES.elem,h+44))}</p><p><strong>중등</strong> — ${esc(pick1(GRADE_WORRIES.mid,h+45))}</p><p><strong>고등</strong> — ${esc(pick1(GRADE_WORRIES.high,h+46))}</p>`);
    }
  }
  const procSec=sec("sproc",pick1(PROC_HEADS,h+47),`<ol>${PROC_STEPS.map(s=>`<li><strong>${esc(s[0])}</strong> — ${esc(s[1])}</li>`).join("")}</ol><p>${esc(pick1(PROC_TIME,h+48))}</p>`);
  const mids=[trait,stuck,method,why,study,localenv,worries,helps];
  const orders=[[6,0,1,7,2,3,4,5],[0,6,2,7,4,1,5,3],[6,1,0,3,7,5,2,4],[1,6,3,0,7,4,5,2],[6,2,1,4,7,0,3,5],[0,1,6,2,7,3,4,5]];
  const midHtml=orders[h%orders.length].map(i=>mids[i]).join("");
  const fqo=pickN(sj.faqs,h+13,4);
  const fqx=fqo.concat([["무료 체험수업이 가능한가요?","네, 30분 무료 체험수업이 가능합니다. 교육팀장 상담 후 안내받은 선생님과 체험수업을 해보고 실수업 진행 여부를 결정하시면 됩니다."],["수업은 보통 어떻게 진행하나요?","가장 많이 선택하는 구성은 주 2회, 회당 1시간~1시간 30분입니다. 학생의 일정과 목표에 맞춰 횟수와 시간은 조정할 수 있습니다."]]);
  const faq=sec("faq",hd("faq",12),fqx.map(q=>`<div class="qa"><p class="q">Q. ${esc(inj(q[0],R,S))}</p><p class="a">${esc(inj(q[1],R,S))}</p></div>`).join(""));
  const close=sec("close",hd("close",14),`<p>${esc(inj(pick1(GENERIC.closing,h+15),R,S))}</p>`);
  return {html:intro+curri+gradeSec+midHtml+procSec+faq+close, faqs:fqx};
}
function bc(items){
  let out=[];
  for(let i=0;i<items.length;i++){const lab=items[i][0],href=items[i][1],last=i===items.length-1;
    out.push((href&&!last)?`<a href="${href}">${esc(lab)}</a>`:`<span class="cur">${esc(lab)}</span>`);}
  return out.join('<span class="sep"> \u203A </span>');
}
